#include "CommonRailsPrinting.hpp"
#include <iomanip>
#include <sstream>
#include <algorithm>
namespace commonrails::printing { std::string PrintField::pad(const std::string&s,int w){return s.size()>=static_cast<size_t>(w)?s:s+std::string(w-s.size(),' ');} void PrintLine::write(std::ostream&o,const std::string&s,int w){size_t p=0;while(p<s.size()){size_t r=s.size()-p,n=std::min<size_t>(w,r);if(r>static_cast<size_t>(w)){size_t c=n;while(c&&s[p+c-1]!=' '&&(p+c>=s.size()||s[p+c]!=' '))--c;if(c)n=c;}o<<s.substr(p,n)<<std::string(w-n,' ')<<'\n';p+=n;while(p<s.size()&&s[p]==' ')++p;}} int PrintProgress::clamp(int p){return std::clamp(p,0,100);} int PrintProgress::cells(int p){return clamp(p)*441/100;} void PrintProgress::write(std::ostream&o,int p){p=clamp(p);o<<"  progress "<<p<<"% ("<<cells(p)<<"/441 cells)\n";} void PrintComponent::write(std::ostream&o,const std::string&n,unsigned long id,unsigned long d,const std::string&m){std::ostringstream s;s<<"-- : [Object ID: "<<std::setw(10)<<std::setfill('0')<<id<<"] [Date: "<<d<<"] [Current: @"<<n<<"] . "<<m<<" .";PrintLine::write(o,s.str());} void PrintFormatter::status(std::ostream&o,PrintState s,const std::string&m){const char*n="ERROR";switch(s){case PrintState::START:n="START";break;case PrintState::WORKING:n="WORKING";break;case PrintState::PROGRESS:n="PROGRESS";break;case PrintState::COMPLETE:n="COMPLETE";break;case PrintState::WARN:n="WARN";break;default:break;}PrintLine::write(o,std::string("[")+n+"] "+m);} void PrintRenderer::square(std::ostream&o,int f){f=std::clamp(f,0,441);for(int r=0;r<21;r++){for(int c=0;c<21;c++){int i=(20-r)*21+(20-c);o<<(i<f?PrintGlyphs::full:PrintGlyphs::empty);}o<<'\n';}} }
